              })}px)`,
            }}
          >
            {title}
          </div>
        ) : null}

        {subtitle ? (
          <div
            style={{
              marginTop: titleSize * 0.42,
              fontSize: titleSize * 0.26,
              letterSpacing: "0.02em",
              color: ink,
              opacity:
                0.65 *
                interpolate(t, [16, 40], [0, 1], {
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                }),
              translate: `0px ${interpolate(
                t,
                [16, 40],
                [titleSize * 0.25, 0],
