        ) : null}
      </AbsoluteFill>

      {footerLeft || footerCenter || footerRight ? (
        <div
          style={{
            position: "absolute",
            left: width * 0.05,
            right: width * 0.05,
            bottom: height * 0.032,
            display: "flex",
            justifyContent: "space-between",
            fontSize: titleSize * 0.22,
            color: ink,
            opacity:
              0.78 *
              interpolate(t, [30, 50], [0, 1], {
